  "summary": "The code contained a critical RCE vulnerability due to the use of eval(). I have replaced this with a safe, sandboxed evaluation approach using the 'mathjs' library, added robust error handling, and included JSDoc documentation to improve maintainability.",
  "fixed_code": "const express = require(\"express\");\nconst { evaluate } = require(\"mathjs\");\n\nconst app = express();\napp.use(express.json());\n\n/**\n * POST /api/formula\n * Evaluates a mathematical formula provided in the request body.\n * @param {string} formula - The mathematical expression to evaluate (max 120 chars).\n */\napp.post(\"/api/formula\", (req, res) => {\n    const { formula } = req.body;\n    if (typeof formula !== \"string\" || formula.length > 120 || !/^[0-9+\\-*/(). ]+$/.test(formula)) {\n        return res.status(400).json({ error: \"Invalid or unsafe formula\" });\n    }\n    try {\n        const value = evaluate(formula);\n        res.json({ value });\n    } catch (err) {\n        res.status(400).json({ error: \"Invalid mathematical expression\" });\n    }\n});\n\napp.listen(3000);"
}
